GRANT UPDATE(unlinked_at) ON files.private_attachment TO app_domain;
DO $$ DECLARE d text;BEGIN d:=pg_get_functiondef('files.guard_attachment()'::regprocedure);d:=replace(d,'IF TG_OP=''UPDATE'' AND NEW.version', 'IF TG_OP=''UPDATE'' AND current_user=''app_domain'' AND NEW.unlinked_at IS DISTINCT FROM OLD.unlinked_at AND NOT EXISTS(SELECT 1 FROM core.command_receipt c WHERE c.workspace_id=NEW.workspace_id AND c.id=NEW.command_receipt_id AND c.command_type=''files.unlink'' AND c.state=''claimed'') THEN RAISE EXCEPTION ''unlink command required'';END IF; IF TG_OP=''UPDATE'' AND NEW.version');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION ops.file_candidates(after_id uuid DEFAULT '00000000-0000-0000-0000-000000000000') RETURNS TABLE(id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT f.id FROM files.private_attachment f WHERE f.id>after_id AND f.status<>'deleted' AND (f.status IN ('quarantined','deleting','rejected') OR f.status='pending_upload' AND (f.uploaded_at IS NOT NULL OR f.expires_at<clock_timestamp()) OR f.unlinked_at<clock_timestamp()-interval '30 days') AND (f.scan_lease_until IS NULL OR f.scan_lease_until<clock_timestamp()) ORDER BY f.id LIMIT 100 $$;
CREATE FUNCTION ops.guard_restore_staging() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF current_user<>'app_domain' THEN RETURN NEW;END IF;
 IF NEW.state<>'previewed' OR NEW.recovery_json IS NOT NULL OR NEW.apply_transaction IS NOT NULL OR NEW.confirmed_at IS NOT NULL OR NEW.started_at IS NOT NULL OR NEW.completed_at IS NOT NULL OR NEW.last_error_code IS NOT NULL OR NEW.recovery_export_run_id IS NOT NULL OR NEW.expires_at>statement_timestamp()+interval '24 hours' OR NOT EXISTS(SELECT 1 FROM core.command_receipt c WHERE c.workspace_id=NEW.workspace_id AND c.id=NEW.command_receipt_id AND c.command_type='portability.preview' AND c.state='claimed') OR encode(NEW.bundle_checksum,'hex') IS DISTINCT FROM NEW.bundle_json->>'checksumSha256' OR encode(sha256(convert_to(ops.canonical_json(NEW.bundle_json-'checksumSha256'),'UTF8')),'hex') IS DISTINCT FROM NEW.bundle_json->>'checksumSha256' THEN RAISE EXCEPTION 'owned immutable preview staging required' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER restore_staging_guard BEFORE INSERT ON ops.restore_run FOR EACH ROW EXECUTE FUNCTION ops.guard_restore_staging();
REVOKE ALL ON FUNCTION ops.guard_restore_staging() FROM PUBLIC;
